import{_ as t,o,c as i,a2 as a}from"./chunks/framework.Cv-B11KK.js";const p=JSON.parse('{"title":"BBEdit LaTeX handoff — current 2026-09-24","description":"","frontmatter":{},"headers":[],"relativePath":"dev/HANDOFF.md","filePath":"dev/HANDOFF.md","lastUpdated":1790342103000}'),s={name:"dev/HANDOFF.md"};function r(n,e,c,d,l,h){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="bbedit-latex-handoff-—-current-2026-09-24" tabindex="-1">BBEdit LaTeX handoff — current 2026-09-24 <a class="header-anchor" href="#bbedit-latex-handoff-—-current-2026-09-24" aria-label="Permalink to &quot;BBEdit LaTeX handoff — current 2026-09-24&quot;">​</a></h1><p>This is the current status. The <a href="./archive/handoff-through-2026-09-24">chronological history</a> contains superseded plans and evidence; its old “remaining” lists are not current tasks.</p><h2 id="preserve-these-constraints" tabindex="-1">Preserve these constraints <a class="header-anchor" href="#preserve-these-constraints" aria-label="Permalink to &quot;Preserve these constraints&quot;">​</a></h2><ul><li>Preserve user edits, especially <code>examples/ui-check/sections/equations.tex</code>.</li><li>Review current repository state before work; the user also works with Claude.</li><li>RaTeX remains an experimental placeholder. Do not install it or change defaults.</li><li>Use temporary directories for scratch work, not the home directory. Edit managed dotfiles through chezmoi. Never force-quit BBEdit or modify user documents in tests.</li><li>Follow <code>AGENTS.md</code>: OCaml product logic, thin Bash/AppleScript glue, no shipped Python. Python native/reference tests run through uv with PEP 723 metadata.</li><li>Builds use opam. Local CI is <code>opam exec -- scripts/ci.sh --report</code>; engine changes also need <code>--engines</code>/<code>--tectonic</code>. GitHub Actions remain manual-only.</li><li>Native acceptance already covers completion, Configure Document, Go to Definition, manual/save previews and the persistent outline. Do not ask for redundant checks.</li></ul><h2 id="completed" tabindex="-1">Completed <a class="header-anchor" href="#completed" aria-label="Permalink to &quot;Completed&quot;">​</a></h2><ul><li>Project/profile builds, diagnostics, cancellation, TeXShop aliases and Skim SyncTeX.</li><li>TexLab completion/navigation; OCaml citation/reference pickers; structural editing, wrapping, placeholders and Undo checks. Shipped Python removal is complete (#4).</li><li>Compact reusable equation preview, cached rendering, current/stale/error states, cancellation ownership, dependency-save refresh and optional contextual service.</li><li>pdfLaTeX/XeLaTeX/LuaLaTeX corpus plus Tectonic online/offline bibliography coverage.</li><li>MacTeX 2026 works with native Biber 2.21. Old distributions were cleaned up. Supported MacTeX baseline is <strong>Biber &gt;= 2.21</strong> with matching biblatex. The dated Tectonic test bundle uses isolated Biber 2.17; do not downgrade system Biber.</li><li>Persistent outline merged in <a href="https://github.com/LouLouLibs/bbtex/pull/26" target="_blank" rel="noreferrer">PR #26</a>: expandable tree, literal search, guarded jumps, saved-source refresh retaining state, one window per root, menu/package integration and cleanup on close. HTML escaping and nonce CSP protect source-controlled display text.</li><li>Outline startup bursts: larger listener queue and immediate request draining; three native passes with 16 concurrent startup requests. Keyboard focus survives refresh. 9,600 entries: BBEdit readiness ~1.23 s, update ~1.53 s including polling; Chromium search ~255 ms, down from ~3.7 s. See the explicit native/browser tests.</li><li><a href="https://github.com/LouLouLibs/bbtex/issues/2" target="_blank" rel="noreferrer">Issue #2</a>: opt-in preview that follows the selection (Toggle Live Selection Preview), implemented. Plan: <a href="./plans/2026-09-24-live-selection-preview">live selection preview</a>. The native check <a href="https://github.com/LouLouLibs/bbtex/blob/main/test/integration/check_live_selection.py" target="_blank" rel="noreferrer"><code>check_live_selection.py</code></a> measured 1.23 s cold / 0.76 s warm (cached) from selection to Current, including the 0.35 s debounce and the poll (2026-09-24, Apple Silicon, BBEdit 15.5.5, pdfLaTeX; local timings, not guarantees). Docs: <a href="./../selection-preview#live-selection">live selection</a>.</li></ul><h2 id="setup-and-diagnostics-merged-in-pr-27" tabindex="-1">Setup and diagnostics (merged in PR #27) <a class="header-anchor" href="#setup-and-diagnostics-merged-in-pr-27" aria-label="Permalink to &quot;Setup and diagnostics (merged in PR #27)&quot;">​</a></h2><p>Doctor adds <code>--bbedit-support DIRECTORY</code>, bounded discovery of renamed packages and nested menu folders, broken/duplicate commands, and save-hook conflict checks. The hook installer writes a checksummed receipt; Doctor distinguishes unchanged, modified and unverified attachments without executing or rewriting them. Receipts are content identity, not a security attestation. Legacy hooks without receipts are adopted only if their full decompiled source matches the installer output.</p><p>Staged installation tests cover package discovery, nested conflicts, safe hook upgrade and removal while preserving unrelated attachments. These are isolated tests on a configured Mac, not proof of first-time setup on a clean machine. Unit checks and staged install/upgrade/removal passed, as did a real packaged pdfLaTeX compilation. Native packaged preview passed at 1.587 s first render / 0.316 s cached reuse, preserving source/selection and avoiding first-open focus theft after a document switch. Issue #1 was updated and closed as completed. Follow <a href="./../setup-troubleshooting">setup troubleshooting</a> for the remaining physical fresh-account/Mac walkthrough and explicit verification boundaries.</p><h2 id="remaining-work" tabindex="-1">Remaining work <a class="header-anchor" href="#remaining-work" aria-label="Permalink to &quot;Remaining work&quot;">​</a></h2><ol><li>Perform the documented fresh-account/Mac acceptance with only the release instructions: install, compile, preview, upgrade/rollback and uninstall. This needs the user on a clean account; it cannot be automated here.</li><li>v0.1.0 is released (tag <code>5d0e850</code> on <code>780bfaa</code>, 2026-09-25): full engine CI passed and <a href="https://github.com/LouLouLibs/bbtex/releases/tag/v0.1.0" target="_blank" rel="noreferrer">https://github.com/LouLouLibs/bbtex/releases/tag/v0.1.0</a> has the arm64 package ZIP, checksum and build info.</li><li>The GitHub.com repository is public (since 2026-09-25) and the docs are at <a href="https://louloulibs.github.io/bbtex/" target="_blank" rel="noreferrer">https://louloulibs.github.io/bbtex/</a> (Pages from <code>gh-pages</code>, deployed with <code>scripts/docs-site.sh deploy</code>). The UMN copy is a secondary remote, <code>umn</code>; its Pages need a UMN login. <code>scripts/mirror-release.sh vX.Y.Z</code> pushes a release tag to github.umn.edu/loualiche/bbtex over SSH (<code>Host github.umn.edu</code> in the chezmoi-managed <code>~/.ssh/config</code>, key <code>github_key</code>), fast-forwards its <code>main</code>, and deploys that tag&#39;s docs to its <code>gh-pages</code>, served at <a href="https://pages.github.umn.edu/loualiche/bbtex/" target="_blank" rel="noreferrer">https://pages.github.umn.edu/loualiche/bbtex/</a>. Run it for every release after tagging.</li><li>v0.2 and later: see the <a href="./../roadmap">roadmap</a>. Headline items are Doctor and build warnings for ignored magic comments, mapping <code>options</code>, <code>parameter</code>, <code>output_directory</code> and <code>% !BIB</code>, plain-English error hints always prefixed <code>[bbtex]</code>, and main-file detection, tracked as issues #29–#33 in the v0.2 milestone (#34 is the tracking issue).</li></ol><p>Housekeeping 2026-09-25: all merged branches were deleted locally and on GitHub; <code>origin</code> has only <code>main</code> and <code>gh-pages</code>. The <a href="./../editor-comparison">editor comparison</a> now covers TeXShop, LaTeXTools and AUCTeX against current features.</p><p>Smaller follow-ups (unsaved snapshots, outline state, live selection polish, test moves) are listed under &quot;After v0.2&quot; in the roadmap. No new renderer or RaTeX adoption is required.</p><h2 id="documentation-site" tabindex="-1">Documentation site <a class="header-anchor" href="#documentation-site" aria-label="Permalink to &quot;Documentation site&quot;">​</a></h2><p>User guides in <code>docs/</code> build into a VitePress site (<code>site/</code>, base <code>/bbtex/</code>) with <code>scripts/docs-site.sh build|preview|deploy</code>. The build fails on dead links; links to repository files outside <code>docs/</code> become GitHub links. <code>deploy</code> pushes the built site to the <code>gh-pages</code> branch from a throwaway clone. GitHub Pages serves that branch at <a href="https://louloulibs.github.io/bbtex/" target="_blank" rel="noreferrer">https://louloulibs.github.io/bbtex/</a>. The preview and outline screenshots in <code>docs/images/</code> are headless Chrome renders of the real pages for a demo paper; Skim, LaTeX Results and the editor were captured from the screen with <code>screencapture -l</code> (needs Screen Recording permission). The site&#39;s build-only dependencies carry Dependabot alerts (Vite 5 and esbuild dev server) with no fix short of the VitePress 2 alpha; nothing from <code>site/</code> ships.</p><h2 id="useful-entry-points" tabindex="-1">Useful entry points <a class="header-anchor" href="#useful-entry-points" aria-label="Permalink to &quot;Useful entry points&quot;">​</a></h2><ul><li><code>lib/outline_window.ml</code>, <code>lib/project_index.ml</code>: persistent outline and saved index.</li><li><code>lib/preview.ml</code>, <code>lib/preview_cache.ml</code>, <code>lib/snippet_page.ml</code>: equation rendering.</li><li><code>lib/doctor.ml</code>, <code>scripts/install-preview-save-hook.sh</code>: inspection and hook safety.</li><li><code>docs/dev/releases.md</code>: current Apple Silicon/local-CI release policy.</li><li>Native tests: <code>check_outline_window.py</code>, <code>check_outline_launcher.py</code>, <code>check_outline_large.py</code>, <code>check_live_preview.py</code>, <code>check_save_preview.py</code>.</li><li>Browser test: <code>check_outline_browser.mjs</code>; see outline notes for temporary Playwright setup. Test names containing “live preview” do not implement issue #2.</li><li>If inherited VIRTUAL_ENV is broken, use <code>env -u VIRTUAL_ENV uv run --no-cache --python /Library/Frameworks/Python.framework/Versions/3.13/bin/python3.13 TEST</code>.</li></ul>',17)])])}const m=t(s,[["render",r]]);export{p as __pageData,m as default};
